INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20801, 'Daniel 6:11', 'Daniel', 6, 11, '&nbsp;نو بيا دا کسان په يو ځائ لاړل او دانيال يې وليدلو چې دُعا يې کوله او د خپل خُدائ پاک نه يې مدد غوښتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20802, 'Daniel 6:12', 'Daniel', 6, 12, '&nbsp;نو بيا هغوئ بادشاه له لاړل او هغۀ ته يې د هغه شاهى حکم په حقله ياداشت ورکړو، ”آيا تاسو دا حکم نۀ وُو جارى کړے چې په راتلونکو دېرشو ورځو کښې هر چا هم بغېر ستا نه اے بادشاه سلامت، د بل معبود او يا انسان عبادت وکړو او يا دُعا يې ترينه وغوښتله هغه به د زمرو په غار کښې واچولے شى؟“ بادشاه ورته جواب ورکړو چې، ”آو، بلکل دا حکم د ميديانو او فارسيانو د قانون په مطابق دے کوم چې نۀ شى بدلېدلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20803, 'Daniel 6:13', 'Daniel', 6, 13, '&nbsp;بيا هغوئ بادشاه ته ووئيل چې، ”دانيال څوک چې يو د يهوداه د جلاوطنو کسانو نه دے، هغه نه ستا پرواه ساتى، اے بادشاه سلامت او نه ستا حکم ته څۀ توجو ورکوى. هغه اوس هم په ورځ کښې درې ځله د خپل خُدائ پاک نه دُعا غواړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20804, 'Daniel 6:14', 'Daniel', 6, 14, '&nbsp;نو کله چې بادشاه دا خبره واورېده، نو هغه ډېر زيات خفه شو. هغۀ دا اراده وکړه چې دانيال بچ کړى او هغۀ ټوله ورځ تر نمر پرېوتو پورې د داسې لارې چارې پېدا کولو کوشش وکړو چې دانيال بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20805, 'Daniel 6:15', 'Daniel', 6, 15, '&nbsp;نو بيا هغه کسان په ډله بادشاه له ورغلل او هغۀ ته يې ووئيل، ”بادشاه سلامت، دا خبره ياد ساته چې، د ميديانو او فارسيانو د قانون په مطابق کوم يو قانون او فرمان چې بادشاه جارى کړى نو هغه بدلېدے نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20806, 'Daniel 6:16', 'Daniel', 6, 16, '&nbsp;نو بيا بادشاه حکم وکړو، او هغوئ دانيال راوستلو او هغه يې د زمرو په غار کښې وروغورزولو. بادشاه دانيال ته ووئيل چې، ”ستا خُدائ پاک د کوم چې تۀ په وفادارۍ خِدمت کوې، هغه دې تا له خلاصون درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20807, 'Daniel 6:17', 'Daniel', 6, 17, '&nbsp;يو ګټ راوړلے شو او د غار په خولۀ کېښودے شو، او بادشاه پرې خپل مهر او د خپلو حاکمانو مهرونه يې پرې ولګول، د دې دپاره چې څوک دانيال بچ نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20808, 'Daniel 6:18', 'Daniel', 6, 18, '&nbsp;نو بيا بادشاه خپل شاهى محل ته واپس شو او هغه شپه يې بې د خوراکه او د هر قسمه عېش عشرت نه بغېر تيره کړه. او هغه ټوله شپه ويښ وو او خوب نۀ ورتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20809, 'Daniel 6:19', 'Daniel', 6, 19, '&nbsp;خو په توره خړه بادشاه پاڅېدو او د زمرو غار ته په تېزۍ سره ورغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20810, 'Daniel 6:20', 'Daniel', 6, 20, '&nbsp;نو کله چې هغه غار ته نزدې ورورسېدو، نو هغۀ دانيال ته په غمژن آواز سره آواز ورکړو، ”اے دانياله، د ژوندى خُدائ خِدمت کوونکيه، ولې ستا خُدائ پاک د چا چې تۀ په وفادارۍ سره عبادت کوې، هغۀ دا وکړے شو چې تا د زمرو نه بچ کړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20811, 'Daniel 6:21', 'Daniel', 6, 21, '&nbsp;دانيال ورله جواب ورکړو، ”بادشاه سلامت، تۀ دې د تل دپاره ژوندے اوسې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20812, 'Daniel 6:22', 'Daniel', 6, 22, '&nbsp;زما خُدائ پاک خپله فرښته راولېږله او هغې د زمرو خولې بندې کړې. هغوئ ما ته هيڅ قسمه نقصان نۀ دے رارسولے، ځکه چې زۀ هغۀ ته بې‌ګناه ثابت شوم. بادشاه سلامت، نۀ ما ستا خلاف څۀ جرم کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20813, 'Daniel 6:23', 'Daniel', 6, 23, '&nbsp;بادشاه په دې بې‌حده خوشحاله شو او حکم يې وکړو چې دانيال د غار نه راوباسئ. او کله چې يې دانيال رابهر کړو، نو په هغۀ يو زخم هم نۀ وو، ځکه چې د هغۀ په خپل خُدائ پاک باور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20814, 'Daniel 6:24', 'Daniel', 6, 24, '&nbsp;بيا د بادشاه په حکم، هغه سړى راوستلے شول چا چې په دانيال د بد نيت نه اِلزام لګولے وو او د زمرو په غار کښې يې د ښځو او بچو سره وروغورزول. د غار بېخ ته د رسېدو نه وړاندې زمرو په هغوئ حمله وکړه او هډُوکى يې ورله ټوټه ټوټه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20815, 'Daniel 6:25', 'Daniel', 6, 25, '&nbsp;نو بيا په ټول مُلک کښې داريوس بادشاه ټولو خلقو، قومونو، او د دُنيا د هرې ژبې ويوونکو ته دا وليکل، ”په تاسو دې سلامتيا او برکت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20816, 'Daniel 6:26', 'Daniel', 6, 26, '&nbsp;زۀ د خپلې بادشاهۍ په هر ځائ کښې خلقو ته دا فرمان جارى کوم چې تاسو ټول د دانيال د خُدائ نه يرېږئ او د هغۀ عزت کوئ. ځکه چې هغه ژوندے خُدائ پاک دے، او همېشه پاتې کېدونکے دے، د هغۀ بادشاهى به هيڅکله نۀ تباه کيږى، او د هغۀ بادشاهى به کله هم نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20817, 'Daniel 6:27', 'Daniel', 6, 27, '&nbsp;هغه بچ کوونکے او ساتونکے دے، هغه په آسمان او زمکه کښې نښې او عجائب څرګندوى. هغۀ دانيال د زمرو د پنجو نه بچ کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20818, 'Daniel 6:28', 'Daniel', 6, 28, '&nbsp;نو دانيال د داريوس بادشاه په حکومت کښې او د فارس د بادشاه خورس په حکومت کښې ډېر مخکښې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20819, 'Daniel 7:1', 'Daniel', 7, 1, '&nbsp;د بابل د بادشاه بيلشضر د بادشاهۍ په اول کال، دانيال چې کله په خپل کټ کښې پروت وو نو هغۀ خوب وليدو او په خوب کښې د هغۀ په خيالونو کښې يوه رويا راغله. هغۀ هغه څۀ وليکل کوم چې هغۀ په خوب کښې وليدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20820, 'Daniel 7:2', 'Daniel', 7, 2, '&nbsp;دانيال وفرمائيل چې، ”په هغه شپه ما په رويا کښې وليدل چې هلته زما په وړاندې د آسمان هواګانې د څلورو خواو نه د سمندر په مخ په تېزه لګېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20821, 'Daniel 7:3', 'Daniel', 7, 3, '&nbsp;نو څلور غټ ځناور، چې د يو بل نه مختلف وُو، د سمندر نه بهر راووتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20822, 'Daniel 7:4', 'Daniel', 7, 4, '&nbsp;اولنے د زمرى په شان وو، او د باز غوندې وزرې يې وې. ما تر هغې پورې ورته کتل ترڅو چې يې وزرې پرې کړے شوې او ودرولے شو او بيا دا لکه د انسان په شان په زمکه په دوو پښو ودرېدلو، او انسانى سوچ ورته ورکړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20823, 'Daniel 7:5', 'Daniel', 7, 5, '&nbsp;نو بيا زما په وړاندې ما دوېم ځناور وليدو، کوم چې د مېلو په شان ښکارېدو. دا په خپل يو طرف باندې اوچت کړے شو، او دۀ درې پښتۍ په خپله خولۀ کښې د غاښونو په مينځ کښې نيولې وې. هغۀ ته وئيل کېدۀ، پاڅه او په غوښو ځان موړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20824, 'Daniel 7:6', 'Daniel', 7, 6, '&nbsp;د دې نه وروستو، ما يو بل ځناور وليدو، هغه لکه د پړانګ په شان وو. او د دۀ په شا لکه د مارغۀ په شان څلور وزرې وې. د دې ځناور څلور سرونه وُو، او دۀ ته يې د حکومت کولو اختيار ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20825, 'Daniel 7:7', 'Daniel', 7, 7, '&nbsp;د دې نه وروستو د شپې ما په خپله رويا کښې څلورم ځناور وليدو چې خطرناک او يروونکے او ډېر طاقتور وو. د اوسپنې غټ غاښونه يې وُو او خپل ښکار به يې په هغې ريچې ريچې کړو او تير به يې کړو او څۀ به چې ترې نه پاتې شو نو هغه به يې د خپلو پښو لاندې کړو. هغه د نورو ټولو ځناورو نه کوم چې مخکښې وُو مختلف وو، او د هغۀ لس ښکرونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20826, 'Daniel 7:8', 'Daniel', 7, 8, '&nbsp;کله چې ما د هغۀ د ښکرونو په حقله سوچ کولو، نو هلته زما د وړاندې يو بل ورکوټے ښکر د هغوئ په مينځ کښې ښکاره شو، او درې وړومبى ښکرونه د هغۀ په وړاندې راوويستلے شول. د هغه ښکر لکه د انسان د سترګو په شان سترګې وې او په خولۀ باندې يې په بې‌پرواهۍ سره لافې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20827, 'Daniel 7:9', 'Daniel', 7, 9, '&nbsp;کله چې ما ورته کتل نو تختونه په خپل ځائ باندې ولګولے شُو، او ازلى ذات په خپل تخت کښېناستو. د هغۀ جامې لکه د واورې په شان سپينې وې، او د هغۀ د سر وېښتۀ لکه د سپينې وړۍ په شان وُو. او هغه د اور په تخت باندې کښېناستو او د پايو نه يې د اور شُغلې ختلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20828, 'Daniel 7:10', 'Daniel', 7, 10, '&nbsp;او د هغۀ د حضور نه د اور درياب راوتلو او د هغۀ په وړاندې روان وو. په زرګونو زرګونو د هغۀ خِدمت له راغلل، او په لکونو هستيانې د هغۀ په وړاندې ودرېدلې. بيا د عدالت دپاره دربار کولاو شو، او کتابونه کولاو کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20829, 'Daniel 7:11', 'Daniel', 7, 11, '&nbsp;ورته مې هم هغه شان کتل ځکه چې هغه ورکوټے ښکر د کبر نه ډکې خبرې کولې. تر هغې پورې مې ورته کتل چې هغه څلورم ځناور مړ کړے شو او د دۀ لاش تباه او بَل شوى اور ته وغورزولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20830, 'Daniel 7:12', 'Daniel', 7, 12, '&nbsp;د هغه نورو درېو واړو ځناورو نه قدرت واخستلے شو، خو هغوئ ته د لږ وخت دپاره د ژوندى پاتې کېدلو اجازت مِلاو شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20831, 'Daniel 7:13', 'Daniel', 7, 13, '&nbsp;نو په هم هغه شپه کښې ما په خپله رويا کښې وليدل، چې هلته زما په وړاندې يو کس لکه د اِبن آدم په شان وو، چې د آسمان د وريځو سره راروان وو. او هغه ازلى ذات ته ورورسېدو او د هغۀ حضور ته حاضر کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20832, 'Daniel 7:14', 'Daniel', 7, 14, '&nbsp;هغۀ ته اختيار، جلال او شاهى طاقت ورکړے شو، د ټولو قومونو، ذاتونو او ژبو خلقو د هغۀ عبادت وکړو. د هغۀ بادشاهى ابدى او نۀ ختمېدونکې ده، د هغۀ بادشاهى به هيڅ کله تباه نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20833, 'Daniel 7:15', 'Daniel', 7, 15, '&nbsp;زۀ دانيال، د هغه هر څۀ په حقله پرېشانه وم څۀ چې ما ليدلى وُو، او زما رويا زۀ ويرولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20834, 'Daniel 7:16', 'Daniel', 7, 16, '&nbsp;نو بيا زۀ هغه ولاړو کسانو ته چې هلته تخت سره نزدې وُو يو له ورغلم او تپوس مې ترې نه وکړو چې د دې هر څۀ مطلب څۀ دے. نو هغۀ ما ته د دې تعبير څۀ داسې وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20835, 'Daniel 7:17', 'Daniel', 7, 17, '&nbsp;دا څلور ځناور څلور بادشاهۍ دى چې د زمکې نه به راوچتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20836, 'Daniel 7:18', 'Daniel', 7, 18, '&nbsp;خو په آخر کښې به د خُدائ تعالىٰ مقدسو خلقو ته بادشاهى مِلاو شى، او هغوئ به په هغې باندې تر ابده پورې بادشاهى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20837, 'Daniel 7:19', 'Daniel', 7, 19, '&nbsp;نو بيا ما غوښتل چې د څلورم ځناور په حقله صحيح مطلب باندې ځان پوهه کړم، کوم چې د نورو ټولو نه مختلف او يروونکے وو. او غاښونه يې د اوسپنې او د پښو پنجې يې د زېړو وې، هغه ځناور چې خپل ښکارونه يې ريچې ريچې کړل او تير يې کړل او څۀ چې ترې نه پاتې شول هغه يې د پښو لاندې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20838, 'Daniel 7:20', 'Daniel', 7, 20, '&nbsp;ما هم غوښتل چې د هغۀ په سر د هغه لسو ښکرونو په حقله معلومات حاصل کړم، د هغه بل ښکر په حقله کوم چې راوختلو، د کوم د راختلو نه مخکښې چې هغه درې وغورزېدل، هغه ښکر چې د نورو نه بيا غټ ښکارېدو او چې سترګې يې د انسان په شان وې، او د دې خولې د کبر خبرې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20839, 'Daniel 7:21', 'Daniel', 7, 21, '&nbsp;کله چې ما دا هر څۀ کتل، نو دې ښکر د مقدسينو خلاف جنګ وکړو او هغوئ ته يې شکست ورکولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20840, 'Daniel 7:22', 'Daniel', 7, 22, '&nbsp;ترڅو چې هغه ازلى ذات راغلو او د خُدائ تعالىٰ د مقدسينو په حق کښې يې د عدالت اعلان وکړو. او بيا هغه وخت راغلو چې هغوئ ته بادشاهى مِلاو شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20841, 'Daniel 7:23', 'Daniel', 7, 23, '&nbsp;نو بيا هغۀ ما ته ووئيل چې، دا څلورم ځناور هغه د دُنيا څلورمه بادشاهى ده کومه چې به په زمکه راښکاره شى. دا به د نورو ټولو بادشاهتونو نه مختلفه وى او دا به ټوله زمکه تيره کړى، او د پښو لاندې او ريچې ريچې به يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20842, 'Daniel 7:24', 'Daniel', 7, 24, '&nbsp;هغه لس ښکرونه لس بادشاهان دى څوک چې به د دې بادشاهۍ نه راشى. د دوئ نه وروستو به يو بل بادشاه پېدا شى، هغه به د مخکښېنو نه مختلف وى، هغه به درې بادشاهان ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20843, 'Daniel 7:25', 'Daniel', 7, 25, '&nbsp;هغه به د خُدائ تعالىٰ خلاف خبرې کوى او د هغۀ په مقدسينو به ظلم وکړى، شريعت او د اخترونو مقرر وخت د بدلولو کوشش به وکړى. مقدسين به هغۀ ته د درې نيمو کالو دپاره حواله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20844, 'Daniel 7:26', 'Daniel', 7, 26, '&nbsp;خو بيا به د هغۀ خلاف عدالت شروع شى، او د هغۀ نه به حکومت واخستلے شى او هغه به هم په مکمل توګه تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20845, 'Daniel 7:27', 'Daniel', 7, 27, '&nbsp;نو بيا به د آسمان لاندې د ټولو بادشاهتونو حکومت، طاقت او لوئى هغه ايماندارانو ته حواله شى چې د خُدائ تعالىٰ خلق دى. د هغۀ بادشاهى به ابدى وى، او ټول حکمرانان به د هغۀ عبادت او تابعدارى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20846, 'Daniel 7:28', 'Daniel', 7, 28, '&nbsp;دا خبره دلته ختمه شوه. زۀ دانيال په خپلو خيالونو کښې پرېشانه وم او زما مخ د يرې نه تک زېړ وو، خو دا خبره ما خپل ځان سره محفوظه وساتله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20847, 'Daniel 8:1', 'Daniel', 8, 1, '&nbsp;د بيلشضر بادشاه د بادشاهۍ په درېم کال، ما دانيال بله رويا وليده، د هغې رويا نه وروستو کومه چې ما مخکښې ليدلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20848, 'Daniel 8:2', 'Daniel', 8, 2, '&nbsp;په رويا کښې ما خپل ځان د سوسه قلعه په خوا کښې د عيلام په صوبه کښې د اولائى نِهر په غاړه ولاړ وليدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20849, 'Daniel 8:3', 'Daniel', 8, 3, '&nbsp;ما وکتل چې هلته زما د وړاندې يو د دوو ښکرو والا ګډ د نِهر په غاړه ولاړ وو، او ښکرونه يې اوږدۀ وُو. او يو ښکر يې د بل نه اوږد وو خو دا وروستو لوئ شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20850, 'Daniel 8:4', 'Daniel', 8, 4, '&nbsp;نو ما وليدل چې هغه ګډ د مغرب او شمال او جنوب طرف ته يې ښکرونه وهل. او يو ځناور هم د هغۀ مقابله نۀ شوه کولے، او هيچا څوک هم د هغۀ د زور نه خلاصولے نۀ شُو. څۀ چې يې زړۀ غوښتل هغه يې کول، هغه ډېر طاقتور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20851, 'Daniel 8:5', 'Daniel', 8, 5, '&nbsp;کله چې ما د دې په حقله سوچ کولو، نو ناڅاپه يو چېلے چې د سترګو په مينځ کښې يې مضبوط ښکر وو د مشرق طرف نه راغلو، هغه زمکې سره د لګېدو نه بغېر د ټولې دُنيا نه راواوړېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20852, 'Daniel 8:6', 'Daniel', 8, 6, '&nbsp;هغه د هغه دوو ښکرو والا ګډ له کوم چې ما د نِهر په غاړه ليدلے وو په تېزه او غصه ورغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20853, 'Daniel 8:7', 'Daniel', 8, 7, '&nbsp;ما هغه وليدو چې په هغه ګډ يې په ډيرې غصې سره حمله وکړه، هغه ګډ يې لاندې راوغورزولو او د هغۀ دواړه ښکرونه يې ټوټه ټوټه کړل. د هغۀ په نسبت هغه ډېر کمزورے وو چې د هغۀ مقابله يې کړے وے، چېلى هغه لاندې په زمکه راوغورزولو او د پښو لاندې يې کړو، او چا هم هغه ګډ د هغۀ د زور نه بچ کولے نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20854, 'Daniel 8:8', 'Daniel', 8, 8, '&nbsp;چېلے ډېر زورَور شو، خو د خپل طاقت آخرى حد ته په رسېدلو باندې د هغۀ لوئ ښکر مات شو، او د دې په ځائ څلور اوچت ښکرونه راوختل چې مخ يې د زمکې څلورو خواو ته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20855, 'Daniel 8:9', 'Daniel', 8, 9, '&nbsp;په هغې کښې د يو ښکر نه بل راووتلو، چې په شروع کښې ورکوټے وو خو هغه د جنوب او مشرق طرف ته او د اِسرائيل د ښائسته مُلک طرف ته اوږد او طاقتور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20856, 'Daniel 8:10', 'Daniel', 8, 10, '&nbsp;دا دومره غټ شو چې آسمانى لښکرو ته ورسېدو، او هغۀ څۀ آسمانى لښکر او ستورى لاندې راوغورزول او د پښو لاندې يې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20857, 'Daniel 8:11', 'Daniel', 8, 11, '&nbsp;هغۀ خپل ځان د آسمانى لښکرو د شهزاده په شان دومره اوچت وګڼلو، او هغۀ ته د روزانه قربانۍ پېش کول يې ختم کړل او د مالِک خُدائ کور يې پليت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20858, 'Daniel 8:12', 'Daniel', 8, 12, '&nbsp;ځکه د سرکشۍ په وجه، آسمانى لښکرې او روزمره قربانى د ښکر قدرت ته ورکړے شُو. او هغه د هر کار په کولو کښې کامياب شو او حقيقت زمکې ته وغورزولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20859, 'Daniel 8:13', 'Daniel', 8, 13, '&nbsp;نو بيا ما واورېدل چې يوې مقدسې فرښتې خبرې کولې او بلې مقدسې فرښتې ورته وفرمائيل چې، ”دا کارونه به ترڅو پورې جارى وى کوم چې په رويا کښې وليدلے شُو؟ ترڅو پورې به دا ګناه د روزمره قربانۍ په بدله کښې کيږى؟ ترڅو پورې به آسمانى لښکرې او د مالِک خُدائ کور د پښو لاندې کيږى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20860, 'Daniel 8:14', 'Daniel', 8, 14, '&nbsp;بيا فرښتې ما ته وفرمائيل، ”دا به تر دوه زره او درې سوه ماښامونو او سحرونو پورې وخت واخلى، او د هغې نه وروستو به د مالِک خُدائ کور دوباره مقدس کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20861, 'Daniel 8:15', 'Daniel', 8, 15, '&nbsp;کله چې ما دانيال دا رويا کتله او په دې د پوهېدلو کوشش مې کولو، نو زما په وړاندې څوک ودرېدو چې لکه د انسان غوندې ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20862, 'Daniel 8:16', 'Daniel', 8, 16, '&nbsp;او ما د اولائى نِهر د غاړې نه د يو سړى آواز واورېدو چې وې فرمائيل، ”اے جبرائيله، دې سړى ته د دې رويا مطلب ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20863, 'Daniel 8:17', 'Daniel', 8, 17, '&nbsp;کله چې هغه ما ته نزدې راغلو چرته چې زۀ ولاړ وم، نو زۀ وويرېدلم او پړمخې په زمکه پرېوتلم. هغۀ ما ته وفرمائيل، ”اے بنى آدمه، په دې پوهه شه چې د دې رويا تعلق د آخرى زمانې سره دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20864, 'Daniel 8:18', 'Daniel', 8, 18, '&nbsp;کله چې هغۀ ما ته خبرې کولې، زۀ بې‌هوشه وم، په زمکه پړمخې پروت وم. بيا هغۀ زۀ ونيولم او په خپلو پښو يې ودرولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20865, 'Daniel 8:19', 'Daniel', 8, 19, '&nbsp;بيا هغۀ ما ته وفرمائيل، ”زۀ د دې دپاره راغلم چې تا ته ووايم چې وروستو د غضب په وخت کښې به څۀ وشى، ځکه چې د دې رويا تعلق د آخرى زمانې سره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20866, 'Daniel 8:20', 'Daniel', 8, 20, '&nbsp;کوم د دوو ښکرو ګډ چې تا وليدو دا د مادى او فارس د بادشاهانو نمائندګى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20867, 'Daniel 8:21', 'Daniel', 8, 21, '&nbsp;دا وېښتو والا چېلے د يونان بادشاه دے، او هغه د سترګو په مينځ کښې لوئ ښکر اولنے بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20868, 'Daniel 8:22', 'Daniel', 8, 22, '&nbsp;هغه څلور ښکرونه کوم چې د هغۀ يو مات شوى ښکر په ځائ راوتلو د دې مطلب دا دے چې د اول بادشاهۍ نه به څلور نورې بادشاهۍ جوړې شى خو يو به هم دومره زور طاقت نۀ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20869, 'Daniel 8:23', 'Daniel', 8, 23, '&nbsp;د دوئ د بادشاهۍ په آخرى ورځو کښې کله چې د دې سرکشى او بدکارى آخرى حد ته ورسيږى، نو يو ظالم او ماهر مکار بادشاه به راوچت شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20870, 'Daniel 8:24', 'Daniel', 8, 24, '&nbsp;هغه به ډېر طاقتور شى، خو دا به د دۀ خپل طاقت نۀ وى. هغه به د حېرانونکى تباهۍ سبب شى او څۀ چې هغه کوى په هغې کښې به کامياب شى. هغه به زورَور خلق او د ايماندارانو قوم تباه کړى. ‏', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20871, 'Daniel 8:25', 'Daniel', 8, 25, '&nbsp;د دوکې په سبب به هغه کامياب شى، او هغه به خپل ځان اوچت وګڼى. کله چې هغوئ ځان محفوظ وګڼى، هغه به ناګهانه ډېر خلق تباه کړى او د شهزادګانو د شهزاده خلاف به راپاڅى. خو بيا به هغه تباه شى، خو دا نه چې د انسان په طاقت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20872, 'Daniel 8:26', 'Daniel', 8, 26, '&nbsp;د ماښامونو او سحرونو د قربانيانو کومه رويا چې تا ته ښودلے شوې ده هغه حقيقى ده، خو دا رويا پټه وساته، ځکه چې دا د ډېر لرې مستقبل په حقله ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20873, 'Daniel 8:27', 'Daniel', 8, 27, '&nbsp;زۀ دانيال، ډيرې ورځې خفه او بيمار وم. بيا زۀ پاڅېدم او د بادشاه کارونو له واپس لاړم. زۀ د دې رويا په وجه خفه وم، دا د پوهې نه بهر وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20874, 'Daniel 9:1', 'Daniel', 9, 1, '&nbsp;د مادى د اخسويرس د زوئ داريوس د بادشاهۍ په اول کال څوک چې د بابليانو بادشاه جوړ شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20875, 'Daniel 9:2', 'Daniel', 9, 2, '&nbsp;د هغۀ د بادشاهۍ په اول کال، زۀ دانيال د مقدسو صحيفو نه پوهه شوم، د مالِک خُدائ د هغه کلام په مطابق چې هغۀ يرمياه نبى له ورکړے وو، چې يروشلم به د اويا کاله پورې وران وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20876, 'Daniel 9:3', 'Daniel', 9, 3, '&nbsp;نو بيا زۀ مالِک خُدائ ته راوګرځېدم او هغۀ ته مې مِنت زارى وکړه او روژه مې ونيوله، او ما د ټاټ جامې واغوستلې او په خپل ځان مې ايره ونوستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20877, 'Daniel 9:4', 'Daniel', 9, 4, '&nbsp;ما خپل مالِک خُدائ نه دُعا وغوښتله او اقرار مې وکړو، ”اے مالِکه، تۀ لوئ او حېرانونکے خُدائ يې، څوک چې د خپلې مينې وعده د هغوئ سره قائمه ساتى څوک چې تا سره مينه کوى او ستا حُکمونه منى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20878, 'Daniel 9:5', 'Daniel', 9, 5, '&nbsp;مونږ ګناه کړې ده او غلط کارونه مو کړى دى. مونږ بدعملى کړې ده او سرکشى مو کړې ده، مونږ ستا د احکاماتو او شريعت نه مخ اړولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20879, 'Daniel 9:6', 'Daniel', 9, 6, '&nbsp;مونږ ستا خِدمت کوونکو پېغمبرانو ته غوږ ونۀ نيولو، چا چې ستا په نوم زمونږ بادشاهانو، زمونږ شهزادګانو او پلار نيکونو، او زمونږ د مُلک ټولو خلقو ته خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20880, 'Daniel 9:7', 'Daniel', 9, 7, '&nbsp;مالِکه، تۀ صادق يې، خو نن ورځ مونږ د يهوداه او يروشلم او د ټول بنى اِسرائيل خلق، نزدې او لرې شرمنده يو، په هغه ټولو مُلکونو کښې چرته چې تا مونږ د خپلو غدارى په وجه خوارۀ کړى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20881, 'Daniel 9:8', 'Daniel', 9, 8, '&nbsp;اے مالِکه خُدايه، مونږ او زمونږ بادشاهان، زمونږ شهزادګان او زمونږ پلار نيکونه په شرمونو شرمنده يُو ځکه چې مونږ ستا خلاف ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20882, 'Daniel 9:9', 'Daniel', 9, 9, '&nbsp;خو مالِک خُدائ زمونږ خُدائ پاک مهربانه او بخښونکے دے، اګر چې مونږ د هغۀ خلاف بغاوت کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20883, 'Daniel 9:10', 'Daniel', 9, 10, '&nbsp;مونږ د خپل مالِک خُدائ تابعدارى نۀ ده کړې او د هغۀ هغه حُکمونه مو نۀ دى منلى کوم چې هغۀ مونږ ته د خپل خِدمت کوونکو پېغمبرانو په ذريعه راکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20884, 'Daniel 9:11', 'Daniel', 9, 11, '&nbsp;ټولو بنى اِسرائيلو ستا د شريعت خلاف ورزى کړې ده، مخ يې ترې نه اړولے دے او ستا د منلو نه يې اِنکار کړے دے. نو په دې وجه هغه لعنتونه او قسم خوړلے شوى افتونه چې د خُدائ پاک د خِدمت کوونکى موسىٰ په شريعت کښې ليکلے شوى دى په مونږ نازل شول، ځکه چې مونږ ستا خلاف ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20885, 'Daniel 9:12', 'Daniel', 9, 12, '&nbsp;تا په مونږ د افت راوستلو په ذريعه څۀ چې دې زمونږ د بادشاهانو په خلاف فرمائيلى وُو هغه دې پوره کړل. د آسمان د لاندې هيڅکله هم داسې افتونه نۀ دى راغلى لکه څنګه چې په يروشلم راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20886, 'Daniel 9:13', 'Daniel', 9, 13, '&nbsp;څنګه چې د موسىٰ په شريعت کښې ليکلے شوى دى، هغه ټول افتونه په مونږ نازل شوى دى، بيا اوس هم مونږ د خپل مالِک خُدائ د رضا حاصلولو دپاره د خپلو ګناهونو نه اوړېدلى نۀ يُو او نۀ مو ستا په حقيقت غور کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20887, 'Daniel 9:14', 'Daniel', 9, 14, '&nbsp;نو مالِک خُدائ هم په مونږ د افت راوستلو څۀ پرواه ونۀ کړه، ځکه چې زمونږ مالِک خُدائ په خپلو ټولو کارونو کښې صادق دے، خو بيا هم مونږ د هغۀ تابعدارى ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20888, 'Daniel 9:15', 'Daniel', 9, 15, '&nbsp;اوس اے مالِکه زمونږ خُدايه، تا چا چې خپل خلق د مِصر نه په خپل زورَور لاس راوويستل او خپل نوم له دې عزت او جلال ورکړو چې تر ننه قائم دے، د دې باوجود هم مونږ ګناه وکړه، مونږ بدکارونه وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20889, 'Daniel 9:16', 'Daniel', 9, 16, '&nbsp;اے مالِکه، په خپلو کارونو کښې تۀ صادق يې، نو په دې وجه تۀ خپله سخته غصه او غضب د خپل ښار يروشلم، ستا مقدس غر نه لرې کړه. زمونږ ګناهونو او زمونږ د پلار نيکونو ګناهونو يروشلم او ستا خلق د ګېرچاپېره قومونو د خندا کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20890, 'Daniel 9:17', 'Daniel', 9, 17, '&nbsp;نو اوس اے مالِکه خُدايه، د خپل خِدمت کوونکى زما دُعا او زارۍ ته غوږ ونيسه. اے مالِکه خُدايه د خپل نوم په خاطر خپل تباه شوى پاک کور ته د رحم په نظر وګوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20891, 'Daniel 9:18', 'Daniel', 9, 18, '&nbsp;اے خُدايه، غوږ ونيسه او واوره، خپلې سترګې کولاو کړه او هغه کنډر شوے ښار وګوره چې ستا په نوم پورې تړلے شوے دے. مونږ تا ته سوال زارى د دې دپاره نۀ کوُو چې مونږ صادقان يُو، خو ځکه چې تۀ ډېر مهربانه يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20892, 'Daniel 9:19', 'Daniel', 9, 19, '&nbsp;اے مالِکه واوره، اے خُدايه مونږ معاف کړه. اے مالِکه زمونږ واوره او عمل پرې وکړه. اے زما خُدايه د خپل ځان د خاطره دې مۀ ايسارېږه، ځکه چې ستا ښار او ستا قوم ستا په نوم پورې تړلے شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20893, 'Daniel 9:20', 'Daniel', 9, 20, '&nbsp;نو چې کله ما خبرې او دُعا کوله او د خپلې ګناه او زما د قوم د بنى اِسرائيلو د ګناه اقرار مې کولو او خپل مالِک خُدائ ته مې د هغۀ د مقدس غر دپاره زارى کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20894, 'Daniel 9:21', 'Daniel', 9, 21, '&nbsp;ما لا دُعا کوله چې جبرائيل، هغه سړے چې ما مخکښې په رويا کښې ليدلے وو ما له په تېزۍ سره راغلو، د ماښام د قربانۍ وخت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20895, 'Daniel 9:22', 'Daniel', 9, 22, '&nbsp;هغۀ زۀ پوهه کړم او ما ته يې وفرمائيل، ”اے دانياله، زۀ اوس راغلم چې تا له پوهه او حکمت درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20896, 'Daniel 9:23', 'Daniel', 9, 23, '&nbsp;څنګه چې تا دُعا شروع کړه نو هغې ته جواب ورکړے شو، زۀ د هغې وئيلو دپاره تا له راغلم ځکه چې تۀ ډېر قدرمند يې. په دې وجه دې پېغام ته په خيال سره غوږ شه او په رويا ځان پوهه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20897, 'Daniel 9:24', 'Daniel', 9, 24, '&nbsp;اويا وارې اووۀ کاله ستا قوم او ستا مقدس ښار دپاره مقرر شوى دى چې په کښې خپله سرکشى ختمه کړئ، او ګناه بنده کړئ، د بدعملۍ کفاره ورکړئ، نۀ ختمېدونکے صداقت قائم کړئ، د پېغمبرى رويا او پېشګوئې تصديق وکړئ او چې د ټولو نه مقدس ځائ مسح کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20898, 'Daniel 9:25', 'Daniel', 9, 25, '&nbsp;په دې غور وکړئ او ځان پرې پوهه کړئ. دوه شپېتۀ وارې اووۀ کاله به تير شى د کوم وخت نه چې د يروشلم د بيا جوړولو حُکم ورکړے شوے دے ترڅو چې مالِک خُدائ مسح کړے شوے بادشاه راشى. يروشلم به سره د کوڅو او حِفاظتى خندقونو جوړ کړے شى، خو کۀ څۀ هم چې په يروونکى وخت کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20899, 'Daniel 9:26', 'Daniel', 9, 26, '&nbsp;د دې دوه شپېتۀ وارې اووۀ کاله نه وروستو به مسح کړے شوے کس قتل کړے شى او هغۀ سره به څۀ نۀ وى. نو په هغه وخت کښې به بيا بل حکمران راوچت شى د چا لښکرې به چې دا ښار او د خُدائ کور تباه کړى. د دې خاتمه به لکه د سېلاب راشى، او د جنګ او د هغې بدبختى به د آخر پورې جارى وى، او د هغې تباهۍ حکم جارى شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20900, 'Daniel 9:27', 'Daniel', 9, 27, '&nbsp;هغه حکمران به د اووۀ کالو دپاره د ډېرو خلقو سره لوظ وکړى او د دې وخت په نيمه کښې به هغه قربانۍ او نذرانې ختمې کړى. او د مالِک خُدائ د کور په اوچت ځائ به يو داسې ناپاکه بُت کېږدى چې تباهى به راولى. او تر هغې پورې به هلته وى ترڅو چې خُدائ پاک هغه خپل اَنجام ته ورسوى کوم چې ورته هغۀ مقرر کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');